import { Accordion, Box, Flex, Heading, HStack, Tag, Text } from "@chakra-ui/react";
import type { ReactNode } from "react";
import type { LatencyBreakdown, RasaExecutionTime, VoiceLatency } from "../../types/conversation";
import { isLatencyBreakdown, isRasaExecutionTime, isVoiceLatency } from "../../utils/latency";

function LatencyPill({ ms }: { readonly ms: number }) {
  return (
    <Tag.Root variant="surface" colorPalette="green" size="lg">
      <Tag.Label>~{ms} ms</Tag.Label>
    </Tag.Root>
  );
}

function LatencySection({
  title,
  children,
}: {
  readonly title: string;
  readonly children: ReactNode[];
}) {
  return (
    <Box gap="1" pb="2">
      <Heading textStyle="sm" pb="1">
        {title}
      </Heading>
      {children}
    </Box>
  );
}

function LatencyRow({ label, valueMs }: { readonly label: string; readonly valueMs: number }) {
  return (
    <HStack justify="flex-start" py="1">
      <Text textStyle="sm">{label}</Text>
      <Heading textStyle="sm">{Math.round(valueMs)} ms</Heading>
    </HStack>
  );
}

function VoiceLatencyBody({ latency }: { readonly latency: VoiceLatency }) {
  return (
    <>
      <LatencyRow label="Time to first byte:" valueMs={latency.tts_time_to_first_byte_ms} />
      <LatencyRow label="TTS total generation:" valueMs={latency.tts_total_time_ms} />
      <BooleanRow label="TTS from cache:" value={latency.read_from_cache ?? false} />
    </>
  );
}

function RasaExecutionBody({ times }: { readonly times: RasaExecutionTime }) {
  return (
    <>
      <LatencyRow label="Command processor:" valueMs={times.command_processor} />
      <LatencyRow label="Total bot turn time:" valueMs={times.prediction_loop} />
    </>
  );
}

function BooleanRow({ label, value }: { readonly label: string; readonly value: boolean }) {
  return (
    <HStack justify="flex-start" py="1">
      <Text textStyle="sm">{label}</Text>
      <Heading textStyle="sm">{value ? "yes" : "no"}</Heading>
    </HStack>
  );
}

function LatencyBreakdownBody({ breakdown }: { readonly breakdown: LatencyBreakdown }) {
  return (
    <Flex flexDir="column" gap="2">
      <LatencySection title="Breakdown">
        {breakdown.command_generator_ms !== undefined && (
          <LatencyRow label="Command processor:" valueMs={breakdown.command_generator_ms} />
        )}
        {breakdown.first_agent_response &&
          breakdown.first_agent_response.llm_time_to_first_token_ms !== undefined && (
            <LatencyRow
              label="Time to first LLM token:"
              valueMs={breakdown.first_agent_response.llm_time_to_first_token_ms}
            />
          )}
        {breakdown.first_voice_response &&
          breakdown.first_voice_response.tts_time_to_first_byte_ms !== undefined && (
            <LatencyRow
              label="Time to first byte:"
              valueMs={breakdown.first_voice_response.tts_time_to_first_byte_ms}
            />
          )}
      </LatencySection>
      <LatencySection title="Additional details">
        {breakdown.first_agent_response &&
          breakdown.first_agent_response.generated_by_llm &&
          breakdown.first_agent_response.llm_total_generation_ms !== undefined && (
            <LatencyRow
              label="LLM total generation:"
              valueMs={breakdown.first_agent_response.llm_total_generation_ms}
            />
          )}
        {breakdown.first_voice_response && (
          <>
            {breakdown.first_voice_response.tts_total_generation_ms !== undefined && (
              <LatencyRow
                label="TTS total generation:"
                valueMs={breakdown.first_voice_response.tts_total_generation_ms}
              />
            )}
            {breakdown.first_voice_response.read_from_cache !== undefined && (
              <BooleanRow
                label="TTS from cache:"
                value={breakdown.first_voice_response.read_from_cache}
              />
            )}
          </>
        )}
        {breakdown.full_turn?.prediction_loop_ms !== undefined && (
          <LatencyRow
            label="Total bot turn time:"
            valueMs={breakdown.full_turn.prediction_loop_ms}
          />
        )}
      </LatencySection>
    </Flex>
  );
}

export function BotLatencyAccordionItem({
  voiceLatency,
  latencyBreakdown,
  executionTimes,
}: {
  readonly voiceLatency?: VoiceLatency;
  readonly latencyBreakdown?: LatencyBreakdown;
  readonly executionTimes?: RasaExecutionTime;
}) {
  let title: string;
  let titleMs: number;
  let body: ReactNode;

  if (isLatencyBreakdown(latencyBreakdown)) {
    title = "User-perceived latency";
    titleMs = Math.round(latencyBreakdown.user_perceived_latency_ms);
    body = <LatencyBreakdownBody breakdown={latencyBreakdown} />;
  } else if (isVoiceLatency(voiceLatency)) {
    title = "Latency per turn";
    titleMs = Math.round(voiceLatency.tts_time_to_first_byte_ms);
    body = <VoiceLatencyBody latency={voiceLatency} />;
  } else if (isRasaExecutionTime(executionTimes)) {
    title = "Latency per turn";
    titleMs = Math.round(executionTimes.command_processor);
    body = <RasaExecutionBody times={executionTimes} />;
  } else {
    return null;
  }

  return (
    <Accordion.Item value="latency">
      <Accordion.ItemTrigger px="0" cursor="pointer">
        <HStack flex="1" justify="flex-start" align="center">
          <Heading textStyle="sm">{title}</Heading>
          <LatencyPill ms={titleMs} />
        </HStack>
        <Accordion.ItemIndicator />
      </Accordion.ItemTrigger>
      <Accordion.ItemContent>
        <Accordion.ItemBody px="0" py="2">
          {body}
        </Accordion.ItemBody>
      </Accordion.ItemContent>
    </Accordion.Item>
  );
}
